package ama.transcript;
import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import static org.junit.jupiter.api.Assertions.*;
class Task11PublicationTransferTest {
 static final class MeasuredRows extends JdbcTemplate {final Map<String,Object> sizes;int calls;MeasuredRows(Map<String,Object> sizes){this.sizes=sizes;}@Override public List<Map<String,Object>> queryForList(String sql,Object... args){calls++;assertTrue(sql.startsWith("SELECT OCTET_LENGTH(request_manifest)"),"Content must not be selected after denied metadata");return List.of(sizes);}}
 @Test void oversizedMeasuredTextNeverIssuesContentSelect(){var read=new ama.contract.ConfigArchiveContracts.ArchiveReadBudget(65536,1000000,100,100,16,10000,16,128,65536,65536,1000000,1024,100,1000,10000);var canonical=new ama.contract.MinutesContracts.CanonicalBudget(1000000,32,100000,65536,10000);var limit=new TranscriptAcquisitionBudget(1000000,1000000,1000000,10000000,10000000,1000000,16,256,256);for(String field:List.of("mb","eb")){var sizes=new HashMap<String,Object>();for(String k:List.of("mb","ms","mu","eb","es","eu"))sizes.put(k,10L);sizes.put(field,2048L);var j=new MeasuredRows(sizes);assertThrows(ama.contract.MinutesContracts.Failure.class,()->PublicationExecutionRead.read(j,limit.ledger(read,canonical,()->false),1024,"task","operation","execution",1));assertEquals(1,j.calls);}}
 static ama.contract.ConfigArchiveContracts.ArchiveReadBudget read(){return new ama.contract.ConfigArchiveContracts.ArchiveReadBudget(65536,10000000,100,100,16,100000,16,128,65536,65536,10000000,65536,1000,10000,100000);}
 static ama.contract.MinutesContracts.CanonicalBudget canonical(){return new ama.contract.MinutesContracts.CanonicalBudget(10000000,32,100000,65536,100000);}
 static TranscriptAcquisitionBudget limits(){return new TranscriptAcquisitionBudget(10000000,10000000,10000000,100000000,100000000,1000000,16,256,256);}
 @SuppressWarnings("unchecked") static <T>T with(T record,String field,long value)throws Exception{var c=record.getClass().getRecordComponents();var types=new Class<?>[c.length];var values=new Object[c.length];for(int n=0;n<c.length;n++){types[n]=c[n].getType();values[n]=c[n].getAccessor().invoke(record);if(c[n].getName().equals(field)){if(types[n]==int.class)values[n]=Math.toIntExact(value);else values[n]=value;}}return (T)record.getClass().getDeclaredConstructor(types).newInstance(values);}
 @Test void workerSubmissionHonorsEveryEffectiveFieldMinimumBeforeTransfer()throws Exception {
  for(String field:List.of("maxManifestBytes","maxStringUtf8Bytes","maxStringUtf16","maxStringBytes")){
   var archive=field.equals("maxStringBytes")?read():with(read(),field,100);var canon=field.equals("maxStringBytes")?with(canonical(),field,100):canonical();var calls=new java.util.concurrent.atomic.AtomicInteger();var jdbc=new JdbcTemplate(){@Override public <T>T queryForObject(String sql,Class<T> type,Object... args){calls.incrementAndGet();return type.cast("x".repeat(101));}};
   var error=assertThrows(ama.contract.MinutesContracts.Failure.class,()->PublicationSubmissionRead.read(jdbc,limits().ledger(archive,canon,()->false),archive.maxManifestBytes(),"actual-task",Map.of("request_manifest_bytes",101L,"request_manifest_scalars",101L,"request_manifest_utf16",101L)),field);assertEquals(ama.contract.MinutesContracts.FailureCode.BUDGET_EXCEEDED,error.code());assertEquals(0,calls.get(),field);
  }
 }
 @Test void countSelectGrowthCannotTransferBeyondAdmittedRows()throws Exception {
  var budget=limits().ledger(read(),canonical(),()->false);var seen=new java.util.concurrent.atomic.AtomicInteger();var jdbc=new JdbcTemplate(){@Override public <T>T queryForObject(String sql,Class<T> type,Object... args){return type.cast(1L);}@Override public List<Map<String,Object>> queryForList(String sql,Object... args){int limit=Integer.parseInt(sql.substring(sql.lastIndexOf(" LIMIT ")+7).replace(" FOR UPDATE", ""));seen.set(limit);assertTrue(limit<=budget.usage()[5],"COUNT=1 admitted two rows but SQL could transfer "+limit);return java.util.stream.IntStream.range(0,Math.min(4,limit)).mapToObj(n->Map.<String,Object>of("id","id"+n)).toList();}};
  var method=PublicationGraph.class.getDeclaredMethod("read",JdbcTemplate.class,MinutesPendingDiscovery.Query.class,boolean.class,TranscriptAcquisitionBudget.Ledger.class);method.setAccessible(true);var q=new MinutesPendingDiscovery.Query("publication",List.of("id"),List.of("id"),"meeting_id=?",List.of("meeting"));var thrown=assertThrows(java.lang.reflect.InvocationTargetException.class,()->method.invoke(null,jdbc,q,false,budget));assertInstanceOf(ama.contract.MinutesContracts.Failure.class,thrown.getCause());assertEquals(ama.contract.MinutesContracts.FailureCode.PROVENANCE_UNAVAILABLE,((ama.contract.MinutesContracts.Failure)thrown.getCause()).code());assertEquals(2,seen.get());
 }
}
